var total workerStatsSnapshot
for i := range s.stats {
    snap := s.stats[i].snapshotAndReset()
    if snap.getCount > 0 || snap.scanCount > 0 {
        var workerAvgGet time.Duration
        if snap.getCount > 0 {
            workerAvgGet = time.Duration(int64(snap.getLatency) / int64(snap.getCount))
        }
        var workerAvgScan time.Duration
        if snap.scanCount > 0 {
            workerAvgScan = time.Duration(int64(snap.scanLatency) / int64(snap.scanCount))
        }
        s.logger.Printf(
            "[perf] worker=%d gets=%d get_errors=%d avg_get=%s scans=%d scan_errors=%d avg_scan=%s",
            i,
            snap.getCount,
            snap.getErrors,
            workerAvgGet,
            snap.scanCount,
            snap.scanErrors,
            workerAvgScan,
        )
    }
    total.getCount += snap.getCount
    total.getErrors += snap.getErrors
    total.getLatency += snap.getLatency
    total.scanCount += snap.scanCount
    total.scanErrors += snap.scanErrors
    total.scanLatency += snap.scanLatency
}
if total.getCount == 0 && total.scanCount == 0 {
    continue
}
var avgGet time.Duration
if total.getCount > 0 {
    avgGet = time.Duration(int64(total.getLatency) / int64(total.getCount))
}
var avgScan time.Duration
if total.scanCount > 0 {
    avgScan = time.Duration(int64(total.scanLatency) / int64(total.scanCount))
}

func loadScanSplit(workers int) (*ebpfPolicy, error) {
    if err := ensureRlimit(); err != nil {
        return nil, err
    }
    pinDir := pinDirectory()
    if err := ensurePinDirectory(pinDir); err != nil {
        return nil, fmt.Errorf("ensure pin directory: %w", err)
    }
    var objs ebpfutil.ScanSplitSelectorObjects
    opts := &ebpf.CollectionOptions{
        Maps: ebpf.MapOptions{PinPath: pinDir},
    }
    if err := ebpfutil.LoadScanSplitSelectorObjects(&objs, opts); err != nil {
        return nil, fmt.Errorf("load scan split objects: %w", err)
    }

    if workers < 0 {
        objs.Close()
        return nil, ErrInvalidConfig("workers must be non-negative")
    }

    var key uint32 = 0
    state := ebpfutil.ScanSplitSelectorSplitState{
        Active: uint32(workers),
    }
    if objs.PebbleSplitState != nil {
        if err := objs.PebbleSplitState.Update(&key, &state, ebpf.UpdateAny); err != nil {
            objs.Close()
            return nil, fmt.Errorf("configure scan split state: %w", err)
        }
    }

    return &ebpfPolicy{
        name:    "scan_split",
        program: objs.SplitUdpSelector,
        close:   objs.Close,
    }, nil
}

